import {mountDevelopment,mountCalendar,mountFinance,mountOrganization,mountProduction} from './modules/management.js';
const STORAGE_KEY='apex-reference-v1';
const defaults={version:1,role:'manager',discipline:'formula',date:'2028-05-18',balance:38.4,notifications:3,readMessages:[],offers:[],projects:[{id:'floor-b',name:'Днище B',category:'Аэродинамика',progress:68,days:2,engineers:18,gain:'+0,18 с / круг',cost:2.4},{id:'cooling',name:'Система охлаждения',category:'Надёжность',progress:36,days:7,engineers:12,gain:'+6 надёжности',cost:1.1}],livery:{base:'#c52e45',secondary:'#15191f',accent:'#d6dce5',finish:'satin',sponsor:'NORD',number:'17'},allocations:{formula:68,gt:22,endurance:10},orders:[],productionLoad:76,settings:{motion:true,compact:false},sponsors:['NORD','APEX Energy','IONIX']};
let state;try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');state=saved?.version===1?{...structuredClone(defaults),...saved}:structuredClone(defaults)}catch{state=structuredClone(defaults)}
let activeRoute='overview',cleanup=null,modalCleanup=null,lastFocus=null,navigationToken=0;
const roleLabels={manager:'Менеджер команды',owner:'Владелец команды',manufacturer:'Производитель'};
const roleNames={manager:'VANTA Racing',owner:'VANTA Group',manufacturer:'VANTA Powertrain'};
const disciplineLabels={formula:'FORMULA WORLD',gt:'GT WORLD SERIES',endurance:'ENDURANCE CUP'};
const navItems=[{id:'overview',name:'Штаб команды',icon:'layout-dashboard',group:'УПРАВЛЕНИЕ'},{id:'people',name:'Пилоты и персонал',icon:'users'},{id:'garage',name:'Гараж',icon:'car-front'},{id:'development',name:'Разработка',icon:'drafting-compass'},{id:'race',name:'Гоночный центр',icon:'radio-tower',live:true},{id:'calendar',name:'Календарь',icon:'calendar-days',group:'МИР АВТОСПОРТА'},{id:'world',name:'Чемпионаты',icon:'trophy'},{id:'market',name:'Рынок и поставщики',icon:'handshake'},{id:'finance',name:'Финансы',icon:'wallet',group:'БИЗНЕС'},{id:'organization',name:'Организация',icon:'building-2',role:'owner'},{id:'production',name:'Производство',icon:'factory',role:'manufacturer'}];
export function icon(name,size=18){const pascal=name.split('-').map(p=>p.charAt(0).toUpperCase()+p.slice(1)).join('');const data=window.lucide?.icons?.[pascal]||window.lucide?.icons?.[name];if(!data)return `<span style="display:inline-block;width:${size}px;height:${size}px"></span>`;return window.lucide.createElement(data,{width:size,height:size,'stroke-width':1.65,'aria-hidden':'true'}).outerHTML}
export function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
export function money(v){if(Math.abs(v)>10000)return new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);return '€'+Number(v).toLocaleString('ru-RU',{maximumFractionDigits:2})+' млн'}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{}}
function setState(patch){try{const latest=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(latest?.version===1)Object.assign(state,latest)}catch{}Object.assign(state,patch);save();updateChrome()}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('check-circle-2',18)+`<span>${esc(message)}</span>`;document.getElementById('toast-root').append(el);setTimeout(()=>el.remove(),4500)}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null}document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.()}
function modal({title,body,footer='',onMount}){if(document.getElementById('modal-root').children.length)closeModal();lastFocus=document.activeElement;const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-modal-close aria-label="Закрыть окно">${icon('x',20)}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';const overlay=root.firstElementChild;overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-modal-close]'))closeModal()});const trap=e=>{if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const fs=[...root.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(x=>!x.disabled);if(!fs.length)return;const a=fs[0],b=fs.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}};document.addEventListener('keydown',trap);modalCleanup=()=>document.removeEventListener('keydown',trap);onMount?.(overlay.querySelector('.modal'));setTimeout(()=>root.querySelector('input,button')?.focus(),50);return overlay.querySelector('.modal')}
const ctx={state,setState,navigate,toast,modal,icon,money,esc,closeModal};
function navMarkup(){return navItems.filter(x=>!x.role||x.role===state.role).map(n=>`${n.group?`<div class="nav-group">${n.group}</div>`:''}<button class="nav-link ${n.id===activeRoute?'active':''}" data-route="${n.id}" ${n.id===activeRoute?'aria-current="page"':''}>${icon(n.icon,18)}<span>${n.name}</span>${n.live?'<span class="nav-live" aria-label="Гонка доступна"></span>':''}${n.id==='development'?`<span class="nav-counter">${state.projects.length}</span>`:''}</button>`).join('')}
function buildShell(){document.getElementById('app').innerHTML=`<div class="app-shell"><div class="drawer-overlay" id="drawer-overlay"></div><aside class="sidebar" id="sidebar"><a href="#overview" class="brand" aria-label="APEX: штаб команды"><div class="brand-stripes"><i></i><i></i><i></i></div><div><div class="brand-word">APEX</div><small>MOTORSPORT MANAGER</small></div></a><button class="team-switch" id="role-switch" aria-label="Сменить игровую роль" aria-expanded="false"><span class="team-monogram">V</span><span><strong id="team-name">${roleNames[state.role]}</strong><small id="role-name">${roleLabels[state.role]}</small></span>${icon('chevrons-up-down',15)}</button><nav class="nav" id="main-nav" aria-label="Основная навигация">${navMarkup()}</nav><div class="nav-fill"></div><div class="sidebar-footer"><span class="user-avatar">AA</span><div><strong>Александр</strong><small>Карьера · сезон 2028</small></div><button class="icon-btn" data-action="settings" aria-label="Настройки">${icon('settings',17)}</button></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><button class="icon-btn desktop-hide" id="menu-toggle" aria-label="Открыть меню">${icon('menu',21)}</button><span class="desktop-hide mobile-brand">APEX</span><div class="topbar-breadcrumb"><b id="top-discipline">${disciplineLabels[state.discipline]}</b><span>/</span><b id="breadcrumb">ШТАБ КОМАНДЫ</b></div><span class="season-chip">2028</span></div><div class="topbar-right"><button class="top-search desktop-only" data-action="search" aria-label="Поиск по игре">${icon('search',17)}<span>Поиск</span><kbd>⌘ K</kbd></button><button class="icon-btn desktop-only" data-action="notifications" aria-label="Уведомления">${icon('bell',18)}<span class="notification-count" id="notification-count">${state.notifications}</span></button><div class="top-date"><strong id="current-date"></strong><span>До гоночного уик-энда</span></div><button class="btn btn-primary" data-action="continue">Продолжить ${icon('play',12)}</button></div></header><main id="content" tabindex="-1"></main></div><nav class="mobile-bottom" aria-label="Быстрая навигация"><button data-route="overview">${icon('layout-dashboard')}<span>Штаб</span></button><button data-route="people">${icon('users')}<span>Команда</span></button><button data-route="garage">${icon('car-front')}<span>Гараж</span></button><button data-route="race">${icon('radio-tower')}<span>Гонка</span></button><button id="bottom-more">${icon('menu')}<span>Ещё</span></button></nav></div>`;document.getElementById('role-switch').onclick=showRoles;document.getElementById('menu-toggle').onclick=toggleDrawer;document.getElementById('bottom-more').onclick=toggleDrawer;document.getElementById('drawer-overlay').onclick=()=>toggleDrawer(false);toggleDrawer(false);updateChrome()}
function toggleDrawer(show){const el=document.getElementById('sidebar');const open=typeof show==='boolean'?show:!el.classList.contains('open');el.classList.toggle('open',open);const hidden=window.innerWidth<=760&&!open;el.inert=hidden;el.setAttribute('aria-hidden',String(hidden));document.getElementById('drawer-overlay').classList.toggle('visible',open);document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));if(!open)document.querySelectorAll('.role-popover,.role-backdrop').forEach(x=>x.remove())}
function updateChrome(){const projectBadge=document.querySelector('[data-route=development] .nav-counter');if(projectBadge)projectBadge.textContent=state.projects.length;const date=new Date(state.date+'T12:00:00');const el=document.getElementById('current-date');if(el)el.textContent=date.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});const until=document.querySelector('.top-date span');if(until){const eventDate=state.discipline==='gt'?'2028-05-27':state.discipline==='endurance'?'2028-05-28':'2028-05-21';const left=Math.ceil((new Date(eventDate+'T12:00:00')-date)/86400000);until.textContent=left>0?`До гонки · ${left} ${left===1?'день':left<5?'дня':'дней'}`:left===0?'Сегодня · гонка':'Уик-энд завершён'}document.getElementById('team-name')?.replaceChildren(document.createTextNode(roleNames[state.role]));document.getElementById('role-name')?.replaceChildren(document.createTextNode(roleLabels[state.role]));const badge=document.getElementById('notification-count');if(badge){badge.textContent=String(state.notifications);badge.hidden=state.notifications===0}const top=document.getElementById('top-discipline');if(top)top.textContent=disciplineLabels[state.discipline];document.body.classList.toggle('reduce-motion',state.settings.motion===false)}
function showRoles(){const existing=document.querySelector('.role-popover');if(existing){document.querySelectorAll('.role-popover,.role-backdrop').forEach(x=>x.remove());document.getElementById('role-switch').setAttribute('aria-expanded','false');return}const el=document.createElement('div');el.className='role-popover';const descriptions={manager:'Состав, техника и гоночная стратегия',owner:'Программы, руководители и инвестиции',manufacturer:'Разработка изделий и поставки клиентам'};const icons={manager:'headset',owner:'building-2',manufacturer:'factory'};el.innerHTML=Object.keys(roleLabels).map(r=>`<button class="role-option ${state.role===r?'active':''}" data-role="${r}">${icon(icons[r],20)}<span><strong>${roleLabels[r]}</strong><small>${descriptions[r]}</small></span>${state.role===r?icon('check',15):''}</button>`).join('');const backdrop=document.createElement('div');backdrop.className='role-backdrop';backdrop.onclick=e=>{e.stopPropagation();el.remove();backdrop.remove();document.getElementById('role-switch').setAttribute('aria-expanded','false')};document.body.append(backdrop,el);document.getElementById('role-switch').setAttribute('aria-expanded','true');el.onclick=e=>{const btn=e.target.closest('[data-role]');if(!btn)return;setState({role:btn.dataset.role});el.remove();backdrop.remove();buildShell();navigate(btn.dataset.role==='owner'?'organization':btn.dataset.role==='manufacturer'?'production':'overview');toast('Активная роль: '+roleLabels[btn.dataset.role])};setTimeout(()=>{const off=e=>{if(!el.contains(e.target)&&!e.target.closest('#role-switch')){el.remove();backdrop.remove();document.getElementById('role-switch')?.setAttribute('aria-expanded','false');document.removeEventListener('click',off)}};document.addEventListener('click',off)},0)}
function disciplineControl(){return `<div class="segmented" aria-label="Дисциплина">${[['formula','Формула'],['gt','GT'],['endurance','Выносливость']].map(([v,l])=>`<button class="${state.discipline===v?'active':''}" data-discipline="${v}">${l}</button>`).join('')}</div>`}
function setDiscipline(v){if(v===state.discipline)return;setState({discipline:v});navigate(activeRoute);toast('Программа: '+({formula:'VANTA Racing · Formula World',gt:'VANTA GT · GT World Series',endurance:'VANTA Endurance · Endurance Cup'}[v]))}
function chart(){return `<svg class="chart-svg" viewBox="0 0 280 83" role="img" aria-label="Остаток средств: с 44 до 38,4 миллиона евро за шесть месяцев"><g stroke="#2a3039" stroke-width=".6"><path d="M0 14H280M0 42H280M0 70H280"/></g><defs><linearGradient id="budgetfade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c83b4d" stop-opacity=".2"/><stop offset="1" stop-color="#c83b4d" stop-opacity="0"/></linearGradient></defs><path d="M1 19L55 30L110 24L165 44L220 40L279 52L279 80L1 80Z" fill="url(#budgetfade)"/><path d="M1 19L55 30L110 24L165 44L220 40L279 52" fill="none" stroke="#c56474" stroke-width="1.8"/><circle cx="279" cy="52" r="3" fill="#df8e9d"/><g fill="#6c7786" font-size="8" font-family="Manrope,sans-serif"><text x="0" y="81">ЯНВ</text><text x="50" y="81">ФЕВ</text><text x="105" y="81">МАР</text><text x="160" y="81">АПР</text><text x="215" y="81">МАЙ</text></g></svg>`}
const standings=[['AURORA Motorsport',146,'#82b5bd'],['SCUDERIA Rosso',123,'#b9414f'],['NORTHSTAR Racing',98,'#e6c66d'],['VANTA Racing',72,'#c83b4d'],['TITAN GP',54,'#8b84b2']];
function mountProgramOverview(container,discipline){
 const gt=discipline==='gt';
 const program=gt?{team:'VANTA GT',title:'Штаб GT-программы',series:'GT World Series',round:'04 / 12',completed:'3 / 12',position:'06',points:38,hero:'GT Series<br>Северное кольцо',day:'27',date:'27 мая',format:'Две гонки по 60 минут',mark:'GT',people:[['ДП','Давид Петров','25 очков в личном зачёте'],['КЗ','Клара Зендер','13 очков в личном зачёте']],standings:[['Sienna Motorsport',96,'#bf985e'],['Aurelia GT',83,'#d9aa64'],['NORTHSTAR GT',71,'#e6c66d'],['Nordic GT',59,'#87a7ad'],['ATLAS Motorsport',44,'#85a79c'],['VANTA GT',38,'#c83b4d']],events:[['27','МАЙ','Северное кольцо','Раунд 4/12 · две гонки по 60 минут'],['11','ИЮН','Альпийский парк','Раунд 5/12 · спринтерский уик-энд']]}:{team:'VANTA Endurance',title:'Штаб выносливости',series:'Endurance Cup',round:'03 / 08',completed:'2 / 8',position:'03',points:54,hero:'6 часов<br>Северного кольца',day:'28',date:'28 мая',format:'6 часов · многоклассовая гонка',mark:'6H',people:[['Л','Ларсен','Пилот экипажа'],['Б','Беннет','Пилот экипажа'],['М','Минами','Пилот экипажа']],standings:[['Vertex Endurance',68,'#87ada1'],['Aurelia Hypercar',61,'#d9aa64'],['VANTA Endurance',54,'#c83b4d'],['Helix Endurance',48,'#76b6bd'],['NORTHSTAR Prototype',39,'#e6c66d']],events:[['28','МАЙ','6 часов Северного кольца','Раунд 3/8 · смена экипажей и трафик']]};
 container.innerHTML=`<div class="screen"><header class="screen-head"><div><div class="eyebrow">${program.team.toUpperCase()} / ЦЕНТР УПРАВЛЕНИЯ</div><h1>${program.title}</h1><p class="screen-subtitle">${program.series} · программа VANTA Group</p></div><div class="head-actions">${disciplineControl()}</div></header><section class="dashboard-hero program-hero"><div class="program-hero-mark" aria-hidden="true">${program.mark}</div><div class="hero-content"><div class="hero-round"><i></i> СЛЕДУЮЩИЙ ЭТАП <span style="opacity:.4">/</span> ${program.round}</div><h2>${program.hero}</h2><div class="hero-meta">${icon('map-pin',13)} Северное кольцо · 5,14 км <b></b> ${gt?'GT':'Прототипы'}</div><div class="hero-bottom"><button class="btn btn-primary" data-program-calendar>${icon('calendar-days',14)} Календарь программы</button><small>${program.date} 2028<br><span style="color:#d1d5dc">${gt?'Спринтерский уик-энд':'Гонка на выносливость'}</span></small></div></div><div class="hero-car-tag program-hero-tag"><div></div><div><strong>${program.team.toUpperCase()}</strong><small>${program.series.toUpperCase()} · 2028</small></div></div></section><div class="kpi-grid"><div class="kpi"><div class="kpi-label">${icon('trophy',15)} Место в чемпионате</div><div class="kpi-value">${program.position}</div><div class="kpi-note">Командный зачёт ${program.series}</div></div><div class="kpi"><div class="kpi-label">${icon('flag',15)} Очки команды</div><div class="kpi-value">${program.points}</div><div class="kpi-note">${gt?'25 + 13 очков двух пилотов':'Общий результат экипажа'}</div></div><div class="kpi"><div class="kpi-label">${icon('calendar-days',15)} Этапов завершено</div><div class="kpi-value">${program.completed}</div><div class="kpi-note">Сезон 2028</div></div><div class="kpi"><div class="kpi-label">${icon('wallet',15)} Резерв VANTA Group</div><div class="kpi-value">${money(state.balance)}</div><div class="kpi-note">Общий резерв гоночных программ</div></div></div><div class="dashboard-main"><div class="dashboard-left"><section class="panel"><header class="panel-head"><h2>${gt?'Пилоты программы':'Экипаж программы'}</h2><span class="chip">${program.team}</span></header><div class="program-roster">${program.people.map(([monogram,name,detail])=>`<div class="program-person"><span class="program-person-monogram">${monogram}</span><div><strong>${name}</strong><small>${detail}</small></div>${gt?'':`<span class="program-person-team">${program.team}</span>`}</div>`).join('')}</div>${gt?'':`<div class="program-crew-total"><span>Ларсен / Беннет / Минами</span><strong>3-е место · 54 очка</strong></div>`}</section><section class="panel"><header class="panel-head"><h2>Ближайшие события</h2><button class="subtle-link" data-program-calendar>Календарь ${icon('chevron-right',12)}</button></header>${program.events.map(([day,month,title,detail])=>`<div class="calendar-mini program-calendar-row"><span class="calendar-date"><b>${day}</b><small>${month}</small></span><div><strong>${title}</strong><small>${detail}</small></div>${icon('flag',15)}</div>`).join('')}</section><section class="panel"><header class="panel-head"><h2>Программа следующего этапа</h2><span class="chip">${program.date}</span></header><div class="program-event-summary"><div><span>Чемпионат</span><strong>${program.series}</strong></div><div><span>Формат</span><strong>${program.format}</strong></div><div><span>Трасса</span><strong>Северное кольцо · 5,14 км</strong></div><div><span>Заявка</span><strong>${program.team}</strong></div></div><div class="program-action-row"><button class="btn" data-route="world">Мир автоспорта</button><button class="btn" data-program-calendar>Расписание этапов</button></div></section></div><div class="dashboard-right"><section class="panel"><header class="panel-head"><h2>Командный зачёт</h2><span class="chip">2028</span></header>${program.standings.map(([name,points,color],i)=>`<div class="standing-row ${name===program.team?'active':''}"><span class="rank">${String(i+1).padStart(2,'0')}</span><strong><i class="team-line" style="--team-color:${color}"></i>${name}</strong><span class="mono">${points}</span></div>`).join('')}<div style="padding:12px 19px"><button class="subtle-link" data-route="world">Полная таблица ${icon('chevron-right',12)}</button></div></section><section class="panel"><header class="panel-head"><h2>Финансовый резерв группы</h2><button class="subtle-link" data-route="finance">Отчёт ${icon('chevron-right',12)}</button></header><div class="budget-trend"><div class="budget-trend-header"><strong>${money(state.balance)}</strong><span class="chip">VANTA GROUP</span></div>${chart()}</div></section><div class="program-preview-note">Гоночный центр эталона показывает демонстрационный этап Formula. Для этой программы доступны состав, календарь и положение в чемпионате.</div></div></div><footer class="dashboard-footer"><span>APEX MOTORSPORT MANAGER · ВИЗУАЛЬНЫЙ ЭТАЛОН 1.0</span><span>Демонстрационная карьера · изменения сохраняются в этом браузере</span></footer></div>`;
 container.querySelectorAll('[data-discipline]').forEach(btn=>btn.onclick=()=>setDiscipline(btn.dataset.discipline));
 container.querySelectorAll('[data-program-calendar]').forEach(btn=>btn.onclick=async()=>{await navigate('calendar');const filter=document.getElementById('calendar-filter');if(filter){filter.value=discipline;filter.dispatchEvent(new Event('change'));document.querySelector(`[data-day="2028-05-${program.day}"]`)?.click();}});
}
function mountOverview(container){const d=state.discipline;const isF=d==='formula';if(!isF){mountProgramOverview(container,d);return;}const program=d==='gt'?'GT':d==='endurance'?'Endurance':'Racing';const header=d==='gt'?'Штаб GT-программы':d==='endurance'?'Штаб выносливости':'Штаб команды';container.innerHTML=`<div class="screen"><header class="screen-head"><div><div class="eyebrow">VANTA ${program.toUpperCase()} / ЦЕНТР УПРАВЛЕНИЯ</div><h1>${header}</h1><p class="screen-subtitle">Каждое решение имеет значение.</p></div><div class="head-actions">${disciplineControl()}</div></header><section class="dashboard-hero"><img src="assets/hero.webp" alt="Болид VANTA Racing в тёмном гараже под верхними прожекторами"><div class="hero-content"><div class="hero-round"><i></i> СЛЕДУЮЩИЙ ЭТАП <span style="opacity:.4">/</span> ${isF?'06 / 18':d==='gt'?'04 / 12':'03 / 08'}</div><h2>${isF?'Гран-при<br>Лазурного берега':d==='gt'?'GT Series<br>Северное кольцо':'6 часов<br>Северного кольца'}</h2><div class="hero-meta">${icon('map-pin',13)} ${isF?'Лазурное кольцо · 4,82 км':'Северное кольцо · 5,14 км'}<b></b>${icon('cloud-sun',14)} 24°C</div><div class="hero-bottom"><button class="btn btn-primary" data-route="race">${icon('flag',14)} Гоночный уик-энд</button><small>${isF?'19—21 мая':'26—28 мая'}<br><span style="color:#d1d5dc">Подготовка к этапу</span></small></div></div><div class="hero-car-tag"><div></div><div><strong>V28 / 017</strong><small>VANTA RACING · 2028 SPEC</small></div></div></section><div class="kpi-grid"><div class="kpi"><div class="kpi-label">${icon('trophy',15)} Место в чемпионате</div><div class="kpi-value">${isF?'04':d==='gt'?'06':'03'} <span class="dim" style="font-size:14px;font-weight:400">/ ${isF?'10':'12'}</span></div><div class="kpi-note"><span class="positive">${icon('trending-up',12)} +1 позиция</span><span>после этапа</span></div></div><div class="kpi"><div class="kpi-label">${icon('flag',15)} Очки команды</div><div class="kpi-value">${isF?'72':d==='gt'?'38':'54'}</div><div class="kpi-note"><span class="positive">+18</span> на последнем этапе</div></div><div class="kpi"><div class="kpi-label">${icon('wallet',15)} Доступный бюджет</div><div class="kpi-value">${money(state.balance)}</div><div class="kpi-note">В рамках бюджета <span class="positive">${icon('check',12)}</span></div></div><div class="kpi"><div class="kpi-label">${icon('heart-handshake',15)} Доверие владельца</div><div class="kpi-value">82<span style="font-size:15px;color:var(--dim);margin-left:4px">/100</span></div><div class="kpi-note"><span class="positive">Стабильно</span><span>· цель: топ-4</span></div></div></div><div class="dashboard-main"><div class="dashboard-left"><section class="panel"><header class="panel-head"><h2>Основной состав</h2><button class="subtle-link" data-route="people">Вся команда ${icon('chevron-right',12)}</button></header><div class="driver-pair">${[['keller','17','Адриан Келлер','89','Холодная кровь','5-е место · 44 очка'],['weber','24','Лукас Вебер','87','Повелитель дождя','8-е место · 28 очков']].map(([im,num,name,rating,trait,rank])=>`<button class="driver-mini" data-person="${im}"><span class="driver-mini-photo"><img src="assets/${im}.webp" alt="${name}"><b class="driver-mini-rating">${rating}</b></span><span class="driver-mini-info"><span class="car-number">№ ${num} / ${im==='keller'?'АВСТРИЯ':'ГЕРМАНИЯ'}</span><h3>${name}</h3><span class="mini-trait">${trait}</span><small>${rank}</small></span></button>`).join('')}</div></section><section class="panel"><header class="panel-head"><h2>На вашем столе <span class="dim" style="margin-left:6px;font-weight:400">03</span></h2><button class="subtle-link" data-action="notifications">Входящие ${icon('chevron-right',12)}</button></header><div class="inbox-list"><button class="inbox-item" data-message="development"><span class="inbox-icon">${icon('drafting-compass',15)}</span><span><strong>Днище B готовится к последним испытаниям</strong><small>Елена Морозова · Технический директор</small></span><time>09:42</time></button><button class="inbox-item" data-message="contract"><span class="inbox-icon">${icon('file-signature',15)}</span><span><strong>Вебер готов обсудить новый контракт</strong><small>Агент пилота · Переговоры</small></span><time>09:15</time></button><button class="inbox-item" data-message="sponsor"><span class="inbox-icon">${icon('handshake',15)}</span><span><strong>NORD: бонус за подиум на следующем этапе</strong><small>Коммерческий отдел · €250 000</small></span><time>Вчера</time></button></div></section><section class="panel"><header class="panel-head"><h2>Развитие болида</h2><button class="subtle-link" data-route="development">Технический центр ${icon('chevron-right',12)}</button></header>${state.projects.slice(0,2).map(p=>`<div class="project-mini"><div class="project-mini-top"><strong>${esc(p.name)}</strong><span class="chip ${p.progress>=100?'green':''}">${p.progress>=100?'Готово к установке':p.progress+'%'}</span></div><div class="progress-track"><span style="width:${p.progress}%"></span></div><div class="project-mini-bottom"><span>${esc(p.category)} · ${p.engineers} инженеров</span><span>${p.days>0?'Осталось '+p.days+' дн.':'Завершён'}</span></div></div>`).join('')}</section></div><div class="dashboard-right"><section class="panel"><header class="panel-head"><h2>Кубок конструкторов</h2><span class="chip">2028</span></header>${standings.map(([n,p,c],i)=>`<div class="standing-row ${i===3?'active':''}"><span class="rank">0${i+1}</span><strong><i class="team-line" style="--team-color:${c}"></i>${n}</strong><span class="mono">${p}</span></div>`).join('')}<div style="padding:12px 19px"><button class="subtle-link" data-route="world">Полная таблица ${icon('chevron-right',12)}</button></div></section><section class="panel"><header class="panel-head"><h2>Ближайшие события</h2>${icon('calendar-days',15)}</header><div class="calendar-mini"><span class="calendar-date"><b>19</b><small>МАЙ</small></span><div><strong>Первый день уик-энда</strong><small>Практика · Лазурное кольцо</small></div><span class="chip">FP1</span></div><div class="calendar-mini" style="border-top:1px solid var(--border)"><span class="calendar-date"><b>20</b><small>МАЙ</small></span><div><strong>Днище B · испытания</strong><small>Завершение разработки</small></div>${icon('wrench',15)}</div></section><section class="panel"><header class="panel-head"><h2>Финансовый резерв</h2><button class="subtle-link" data-route="finance">Отчёт ${icon('chevron-right',12)}</button></header><div class="budget-trend"><div class="budget-trend-header"><strong>${money(state.balance)}</strong><span class="chip green">План соблюдён</span></div>${chart()}</div></section></div></div><footer class="dashboard-footer"><span>APEX MOTORSPORT MANAGER · ВИЗУАЛЬНЫЙ ЭТАЛОН 1.0</span><span>Демонстрационная карьера · изменения сохраняются в этом браузере</span></footer></div>`;container.querySelectorAll('[data-person]').forEach(btn=>btn.onclick=()=>{setState({selectedPerson:btn.dataset.person});navigate('people')});container.querySelectorAll('[data-discipline]').forEach(btn=>btn.onclick=()=>setDiscipline(btn.dataset.discipline))}
const messages={development:{title:'Днище B: финальные испытания',from:'Елена Морозова · Технический директор',body:'Мы завершили основной цикл продувок. Новое днище должно улучшить темп на быстрых участках примерно на 0,18 секунды на круг. Финальная проверка надёжности займёт ещё два дня.',action:'Открыть разработку',route:'development'},contract:{title:'Лукас Вебер: продление контракта',from:'Отдел по работе с пилотами',body:'Лукас доволен атмосферой в команде и готов обсудить ещё два сезона. Его агент предлагает зарплату €4,8 млн в год и равный статус с напарником.',action:'Начать переговоры',route:'market'},sponsor:{title:'NORD: специальный бонус',from:'Коммерческий отдел',body:'За место на подиуме на Гран-при Лазурного берега NORD выплатит дополнительный бонус €250 000. Для выполнения условия логотип должен оставаться на боковых понтонах болида.',action:'Открыть спонсоров',route:'finance'}};
function openMessage(id){const m=messages[id];const read=[...new Set([...state.readMessages,id])];setState({readMessages:read,notifications:Math.max(0,3-read.length)});modal({title:m.title,body:`<p class="eyebrow">${m.from}</p><p>${m.body}</p><div class="modal-callout">Сообщение относится к текущему демонстрационному сохранению.</div>`,footer:`<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="message-action">${m.action}</button>`,onMount:el=>{el.querySelector('#message-action').onclick=()=>{closeModal();navigate(m.route)}}})}
function notifications(){modal({title:'Входящие сообщения',body:`<div class="inbox-list">${Object.entries(messages).map(([id,m])=>`<button class="inbox-item" data-inbox="${id}"><span class="inbox-icon">${icon(state.readMessages.includes(id)?'mail-open':'mail',16)}</span><span><strong>${m.title}</strong><small>${m.from}</small></span>${state.readMessages.includes(id)?'':`<span class="status-dot" style="color:var(--accent)"></span>`}</button>`).join('')}</div>`,onMount:el=>el.querySelectorAll('[data-inbox]').forEach(b=>b.onclick=()=>openMessage(b.dataset.inbox))})}
function search(){modal({title:'Поиск по игре',body:`<input class="search-field" type="search" id="global-search" placeholder="Раздел, пилот, разработка…" aria-label="Поиск"><div class="search-results" id="search-results"></div>`,onMount:el=>{const inp=el.querySelector('input'),out=el.querySelector('#search-results');const all=[...navItems.filter(n=>!n.role||n.role===state.role).map(n=>({name:n.name,route:n.id,icon:n.icon,type:'Раздел'})),{name:'Адриан Келлер',route:'people',icon:'user',type:'Пилот'},{name:'Лукас Вебер',route:'people',icon:'user',type:'Пилот'},{name:'Днище B',route:'development',icon:'drafting-compass',type:'Разработка'},{name:'NORD',route:'finance',icon:'handshake',type:'Спонсор'}];const render=()=>{const found=all.filter(x=>x.name.toLowerCase().includes(inp.value.toLowerCase())).slice(0,9);out.innerHTML=found.length?found.map(x=>`<button class="search-result" data-goto="${x.route}">${icon(x.icon,17)}<span>${x.name}</span><small>${x.type}</small></button>`).join(''):'<div class="empty-state">Ничего не найдено. Попробуйте другое название.</div>';out.querySelectorAll('button').forEach(b=>b.onclick=()=>{closeModal();navigate(b.dataset.goto)})};inp.oninput=render;render();inp.focus()}})}
function settings(){modal({title:'Настройки эталона',body:`<div class="toggle-row"><div><strong>Анимации интерфейса</strong><small>Переходы между экранами и панелями</small></div><input type="checkbox" class="toggle" id="motion-setting" aria-label="Анимации" ${state.settings.motion?'checked':''}></div><div class="toggle-row"><div><strong>Локальное сохранение</strong><small>Ливрея, проекты, предложения и бюджет сохраняются автоматически.</small></div>${icon('hard-drive',20)}</div><div style="padding-top:20px"><h3>Визуальный эталон · 1.0</h3><p class="muted" style="margin-top:9px">Макет охватывает три роли и основные системы игры. Экономика и гонка демонстрируют взаимодействия интерфейса; полноценная симуляция появится при разработке.</p><p class="prototype-note">Команды, персонажи, регламенты, результаты и суммы вымышлены. Геометрия автомобилей условная.</p></div>`,footer:`<button class="btn" id="reset-demo">${icon('rotate-ccw',14)} Сбросить демо</button><button class="btn btn-primary" data-modal-close>Готово</button>`,onMount:el=>{el.querySelector('#motion-setting').onchange=e=>setState({settings:{...state.settings,motion:e.target.checked}});el.querySelector('#reset-demo').onclick=()=>modal({title:'Сбросить демонстрационное сохранение?',body:'Будут восстановлены исходные цвета автомобиля, бюджет, дата и состав проектов. Это действие относится только к макету.',footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="confirm-reset">Сбросить</button>',onMount:e=>e.querySelector('#confirm-reset').onclick=()=>{cleanup?.();cleanup=null;Object.keys(state).forEach(k=>delete state[k]);Object.assign(state,structuredClone(defaults));save();closeModal();buildShell();navigate('overview');toast('Демонстрационное сохранение восстановлено')}})}})}
function advance(){if(activeRoute==='race'){toast('Время гонки управляется кнопкой старта в гоночном центре.');return}const dt=new Date(state.date+'T12:00:00');dt.setUTCDate(dt.getUTCDate()+1);const projects=state.projects.map(p=>({...p,days:Math.max(0,p.days-1),progress:p.days<=1?100:Math.min(99,p.progress+Math.ceil((100-p.progress)/p.days))}));setState({date:dt.toISOString().slice(0,10),projects});navigate(activeRoute);const ready=projects.filter(p=>p.progress===100&&!p.installed);toast(ready.length?`${ready[0].name}: разработка завершена. Можно установить на болид.`:'Новый день. Сроки проектов обновлены.')}
async function navigate(route){const navToken=++navigationToken;const targetNav=navItems.find(x=>x.id===route);if(!targetNav||(targetNav.role&&targetNav.role!==state.role))route='overview';cleanup?.();cleanup=null;activeRoute=route;toggleDrawer(false);document.querySelectorAll('.role-popover,.role-backdrop').forEach(x=>x.remove());document.getElementById('main-nav').innerHTML=navMarkup();document.getElementById('breadcrumb').textContent=(navItems.find(n=>n.id===route)?.name||'Штаб').toUpperCase();document.querySelectorAll('.mobile-bottom [data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));if(location.hash.slice(1)!==route)history.replaceState(null,'','#'+route);const content=document.getElementById('content');content.innerHTML='';window.scrollTo({top:0,behavior:'instant'});try{if(route==='overview'){if(state.role==='owner')cleanup=mountOrganization(content,ctx);else if(state.role==='manufacturer')cleanup=mountProduction(content,ctx);else mountOverview(content)}else if(route==='garage'){const m=await import('./modules/garage.js');if(activeRoute===route&&navToken===navigationToken)cleanup=m.mountGarage(content,ctx)}else if(route==='race'){const m=await import('./modules/race.js');if(activeRoute===route&&navToken===navigationToken)cleanup=m.mountRace(content,ctx)}else if(['people','market','world'].includes(route)){const m=await import('./modules/people.js');if(activeRoute===route&&navToken===navigationToken)cleanup=m[{people:'mountPeople',market:'mountMarket',world:'mountWorld'}[route]](content,ctx)}else cleanup=({development:mountDevelopment,calendar:mountCalendar,finance:mountFinance,organization:mountOrganization,production:mountProduction}[route])(content,ctx);updateChrome()}catch(err){console.error(err);content.innerHTML=`<div class="error-screen"><h1>Раздел не удалось открыть</h1><p>Повторите переход. Если ошибка сохранится, обновите страницу.</p><button class="btn" data-route="overview">Вернуться в штаб</button></div>`}}
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]');if(r){e.preventDefault();closeModal();navigate(r.dataset.route);return}const a=e.target.closest('[data-action]')?.dataset.action;if(a){({settings,notifications,search,continue:advance}[a])?.();return}const msg=e.target.closest('[data-message]')?.dataset.message;if(msg)openMessage(msg)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}if(e.key==='Escape'){toggleDrawer(false);document.querySelectorAll('.role-popover,.role-backdrop').forEach(x=>x.remove())}});
window.addEventListener('resize',()=>{const sidebar=document.getElementById('sidebar');if(sidebar){const hidden=window.innerWidth<=760&&!sidebar.classList.contains('open');sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden))}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
buildShell();navigate(location.hash.slice(1)||'overview');
